const paths=['home','assets','products','transfer','events','rewards'];
const icons=['<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>','<rect x="3" y="5" width="18" height="15" rx="3"/><path d="M3 8h18m-5 4h5v5h-5zM5 5V3h13"/>','<path d="m3 17 6-6 4 3 8-10m-6 0h6v6"/>','<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>','<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v5m10-5v5M3 11h18"/>','<rect x="3" y="9" width="18" height="4" rx="1"/><path d="M5 13v8h14v-8M12 9v12c0-9 0-17-4-17-5 0-3 6 4 5 7 1 9-5 4-5-4 0-4 8-4 5"/>'];
const icon=i=>`<span class="nav-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[i%6]}</svg></span>`;
let sector='coin';try{sector=localStorage.getItem('flow-sector')||'coin'}catch{}if(!SECTORS[sector])sector='coin';let tab='all';let sessions={coin:[],logistics:[],startup:[]};const $=s=>document.querySelector(s);const c=()=>SECTORS[sector];const esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));let route=()=>paths.includes(location.hash.slice(1))?location.hash.slice(1):'home';
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function modal(title,body){$('#dialog-content').innerHTML=`<h2>${title}</h2>${body}`;$('#dialog').showModal()}
function switchSector(value){if(!SECTORS[value])throw Error('지원하지 않는 업종입니다.');sector=value;tab='all';try{localStorage.setItem('flow-sector',sector)}catch{}$('#sector').value=sector;render()}
function title(){let index=paths.indexOf(route());return `<div class="heading"><div><div class="eyebrow">${c().english} / YOUR DAILY FLOW</div><h1>${index===0?'좋은 아침이에요, <strong>테리님.</strong>':c().menus[index]}</h1><p>${index===0?'오늘도 좋은 흐름을 만들어보세요.':{assets:'중요한 현황을 한곳에서 확인하세요.',products:'지금 나에게 맞는 선택을 찾아보세요.',transfer:sector==='coin'?'네트워크 간 자산 이동을 미리 확인하세요.':sector==='logistics'?'배송할 물품과 수령 정보를 입력하세요.':'필요한 상담과 일정을 선택하세요.',events:'새로운 소식과 놓치기 아쉬운 혜택.',rewards:'함께할수록 더해지는 혜택.'}[route()]}</p></div><span class="date">2026년 9월 23일 수요일</span></div><div class="mobile-switch"><label class="sector-label" for="mobile-sector">워크스페이스 전환</label><select id="mobile-sector">${Object.entries(SECTORS).map(([k,v])=>`<option value="${k}" ${sector===k?'selected':''}>${v.name} · ${v.english}</option>`).join('')}</select></div>`}
function balance(){return `<section class="balance"><div class="balance-label">${c().balanceLabel}${icon(1)}</div><div class="money">${c().balance}<small>${c().unit}</small></div><div class="equiv">${c().equivalent}<span class="change">↗ ${c().change}</span></div><div class="balance-bottom"><span>${sector==='coin'?'내 지갑 · 0x7a2F…8e41':sector==='logistics'?'FLOW 물류센터 · 서울':'FLOW 스튜디오 · 개인 사업자'}</span><button data-goto="assets">${c().action} ↗</button></div></section>`}
function stats(){return `<section class="stats">${c().stats.map((s,i)=>`<div class="stat"><div class="stat-label">${s[0]}<span>↗</span></div><strong>${s[1]}</strong><small>${s[2]}</small></div>`).join('')}</section>`}
function assets(full=false){return `<section class="panel"><div class="section-top"><h2>${c().listTitle}</h2>${!full?'<button class="text-button" data-goto="assets">전체 보기 ↗</button>':'<span class="demo">예시 목록</span>'}</div><div class="list-wrap"><table class="asset-list"><thead><tr>${c().columns.map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${c().rows.map((r,i)=>`<tr><td><div class="asset-name"><span class="token t${i}">${sector==='coin'?r[0][0]:'0'+(i+1)}</span><b>${r[0]}<small>${r[1]}</small></b></div></td><td>${r[2]}</td><td>${r[3]}</td><td class="${r[4].startsWith('−')?'negative':'positive'}">${r[4]}</td></tr>`).join('')}</tbody></table></div></section>`}
function activity(){return `<section class="panel"><div class="section-top"><h2>최근 활동</h2><span class="text-button">최근 3건</span></div>${c().activity.map((a,i)=>`<div class="activity">${icon(i===0?5:3)}<div><b>${a[0]}</b><small>${a[1]}</small></div><strong>${a[2]}</strong></div>`).join('')}</section>`}
function quick(){let labels=sector==='coin'?['보내기','받기','스왑','QR 코드']:sector==='logistics'?['출고 접수','배송 조회','배송 상품','혜택 보기']:['상담 신청','사업 현황','지원 사업','혜택 보기'];return `<section class="quick"><div class="section-top"><h2>빠른 실행</h2><span class="text-button">QUICK ACCESS</span></div><div class="quick-grid">${labels.map((t,i)=>`<button data-quick="${i}">${icon([3,1,2,5][i])}${t}</button>`).join('')}</div><p>${sector==='coin'?'자산의 이동과 관리를 더 간편하게.':'자주 사용하는 업무를 바로 시작하세요.'}</p></section>`}
function home(){return `<div class="top-grid">${balance()}${quick()}</div>${stats()}<div class="body-grid"><div>${assets()}${activity()}</div><div><section class="promo"><span class="pill">${sector==='coin'?'GROW YOUR ASSETS':sector==='logistics'?'MOVE WITH FLOW':'BUILD YOUR NEXT'}</span><h2>${c().promo}</h2><p>${c().promoSub}</p><button class="primary" data-goto="products">${c().menus[2]} 살펴보기 ↗</button></section><section class="panel referral"><span class="gift">${icon(5)}</span><div><h2>함께하면 더 좋은 혜택</h2><p>친구를 초대하고 보상을 받으세요.</p></div><button class="secondary" data-goto="rewards">초대 ↗</button></section></div></div>`}
function products(){return `<div class="tabs"><button data-tab="all" class="${tab==='all'?'selected':''}">${c().menus[2]}</button><button data-tab="mine" class="${tab==='mine'?'selected':''}">내 신청 <small>${sessions[sector].length}</small></button></div>${tab==='mine'?`<section class="panel">${sessions[sector].length?sessions[sector].map(s=>`<div class="activity"><div><b>${esc(s)}</b><small>이번 세션 · 데모 신청</small></div><strong>접수 완료</strong></div>`).join(''):'<div class="empty">아직 신청한 내역이 없습니다.<p>상품을 살펴보고 나에게 맞는 항목을 선택해보세요.</p></div>'}</section>`:`<div class="products">${c().products.map((p,i)=>`<article class="product ${i===2?'featured':''}"><span class="eyebrow">${i===2?'PREMIUM':'0'+(i+1)}</span><h3>${p[0]}</h3><p>${p[1]}</p><div class="rate">${p[2]} <small style="font-size:13px;font-weight:400">${sector==='coin'?'예시 APY':''}</small></div><dl><dt>${sector==='coin'?'예치 기간':'이용 기간'}</dt><dd>${p[3]}</dd><dt>${sector==='coin'?'최소 예치':'최소 신청'}</dt><dd>${Number(p[4]).toLocaleString()} ${sector==='coin'?'FLOW':sector==='logistics'?'건':'명'}</dd></dl><button class="primary" data-product="${i}">${sector==='coin'?'예치 미리보기':'신청하기'}</button></article>`).join('')}</div><p class="notice">${sector==='coin'?'금리와 잔액은 화면 확인용 예시입니다. 실제 예치나 자산 이동은 발생하지 않습니다.':'신청은 이 화면에서만 확인하는 데모이며, 실제 업무 시스템으로 전송되지 않습니다.'}</p>`}`}
function transfer(){if(sector==='coin')return `<section class="panel form-panel"><div class="section-top"><h2>브리지</h2><span class="demo">시뮬레이션</span></div><form id="transfer-form"><label class="field">보내는 네트워크<select id="from"><option>Ethereum</option><option>Flow Chain</option></select></label><label class="field">수량 · FLOW<input id="amount" type="number" min="0.01" max="6000" step="0.01" value="100" required></label><button type="button" class="secondary" data-action="reverse">⇅ 방향 바꾸기</button><div class="field">받는 네트워크<strong id="to">Flow Chain</strong></div><div class="notice">전환 비율 1:1 · 예상 수령 <b id="estimate">100</b> FLOW<br>실제 수수료는 네트워크 연결 후 계산됩니다.</div><button class="primary">전환 내역 미리보기</button></form></section>`;return `<section class="panel form-panel"><h2>${c().menus[3]}</h2><form id="request-form"><label class="field">${sector==='logistics'?'수령인':'신청자'}<input name="name" autocomplete="name" required placeholder="이름을 입력하세요" maxlength="40"></label><label class="field">${sector==='logistics'?'배송 주소':'상담 주제'}<input name="topic" required placeholder="${sector==='logistics'?'상세 주소를 입력하세요':'상담받고 싶은 내용을 입력하세요'}" maxlength="200"></label><label class="field">${sector==='logistics'?'출고 희망일':'상담 희망일'}<input name="date" type="date" required></label><p class="notice">실제 접수 전 화면을 확인하는 데모입니다. 입력 내용은 서버에 저장되지 않습니다.</p><button class="primary">신청 내용 확인</button></form></section>`}
function events(){return `<div class="tabs"><button data-tab="all" class="${tab==='all'?'selected':''}">이벤트</button><button data-tab="news" class="${tab==='news'?'selected':''}">공지사항</button></div><div class="news-grid">${(tab==='news'?['워크스페이스 이용 안내','서비스 업데이트 안내']:['함께 시작하는 웰컴 혜택',sector==='coin'?'내 자산의 새로운 가능성':sector==='logistics'?'첫 배송을 함께해요':'새로운 시작을 응원합니다']).map((t,i)=>`<article class="panel"><div class="news-art ${i?'dark':''}">${i?'YOUR NEXT, WITH FLOW.':'HELLO, FLOW.'}</div><p>${tab==='news'?'NOTICE':'EVENT'} · 2026.09.23</p><h2>${t}</h2><p>${tab==='news'?'더 편리하게 이용할 수 있도록 주요 내용을 안내합니다.':'새로운 워크스페이스에서 나에게 맞는 혜택을 확인하세요.'}</p><button class="secondary" data-news="${esc(t)}">자세히 보기 ↗</button></article>`).join('')}</div>`}
function rewards(){return `<div class="top-grid">${balance()}<section class="panel reward-code"><h2>나의 추천코드</h2><strong>FLOW26</strong><button class="secondary" data-action="copy">코드 복사</button> <button class="primary" data-action="share">공유하기</button></section></div>${stats()}<section class="panel"><h2>내 추천 현황</h2><div class="empty">아직 초대한 친구가 없습니다.<p>추천코드를 공유하고 함께 시작해보세요.</p></div></section>`}
function render(){const active=route();document.documentElement.style.setProperty('--accent',c().accent);$('#sector').value=sector;for(const id of ['desktop-nav','mobile-nav'])$('#'+id).innerHTML=paths.map((p,i)=>`<a href="#${p}" class="${active===p?'active':''}" ${active===p?'aria-current="page"':''}>${icon(i)}<span>${c().menus[i]}</span></a>`).join('');$('#breadcrumb').textContent=`${c().name} 워크스페이스 / ${c().menus[paths.indexOf(active)]}`;$('#main').innerHTML=title()+({home,assets:()=>`<div class="top-grid">${balance()}${quick()}</div>${stats()}${assets(true)}${activity()}`,products,transfer,events,rewards}[active])();document.title=`${c().menus[paths.indexOf(active)]} · ${c().name} | FLOW`}
$('#sector').addEventListener('change',e=>switchSector(e.target.value));document.addEventListener('change',e=>{if(e.target.id==='mobile-sector'||e.target.id==='settings-sector')switchSector(e.target.value);if(e.target.id==='from')$('#to').textContent=e.target.value==='Ethereum'?'Flow Chain':'Ethereum'});document.addEventListener('input',e=>{if(e.target.id==='amount')$('#estimate').textContent=Number(e.target.value||0).toLocaleString()});window.addEventListener('hashchange',()=>{tab='all';render();window.scrollTo(0,0)});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.goto){location.hash=b.dataset.goto;return}if(b.dataset.tab){tab=b.dataset.tab;render();return}if(b.dataset.quick!==undefined){let i=Number(b.dataset.quick);if(sector!=='coin'){location.hash=['transfer','assets','products','rewards'][i];return}if(i===0||i===2){modal(i===0?'보내기':'스왑',`<p>실제 지갑을 연결하면 사용할 수 있는 기능입니다. 현재는 화면 확인용 데모입니다.</p><button class="primary" data-action="bridge">브리지 시뮬레이션 보기</button>`)}else modal(i===1?'내 지갑 주소':'QR 코드',`<p>현재 연결된 실제 지갑이 없습니다. 데모 주소를 실제 입금에 사용하지 않도록 입금용 주소와 QR은 제공하지 않습니다.</p>`);return}if(b.dataset.product!==undefined){let i=Number(b.dataset.product),p=c().products[i];modal(p[0],`<p>${p[3]} · ${p[2]} ${sector==='coin'?'예시 APY':''}</p><p>${sector==='coin'?'실제 토큰 이동 없이 신청 흐름을 확인합니다.':'실제 접수 없이 신청 흐름을 확인합니다.'}</p><button class="primary" data-confirm-product="${i}">데모 신청 완료하기</button>`);return}if(b.dataset.confirmProduct!==undefined){const p=c().products[Number(b.dataset.confirmProduct)];sessions[sector].push(p[0]);$('#dialog').close();tab='mine';render();toast('데모 신청이 완료되었습니다.');return}if(b.dataset.news){modal(esc(b.dataset.news),`<p>FLOW의 ${c().name} 워크스페이스에 오신 것을 환영합니다.</p><p>홈에서 현황을 확인하고, ${c().menus[2]}에서 이용 가능한 항목을 살펴볼 수 있습니다. 추천코드는 보상 메뉴에서 확인하세요.</p><p class="notice">이 콘텐츠는 화면 확인용 예시입니다. 실제 이벤트 조건은 운영 시 등록합니다.</p>`);return}const a=b.dataset.action;if(a==='profile')modal('워크스페이스 설정',`<p>테리 · 내 워크스페이스</p><label class="field">표시 업종<select id="settings-sector">${Object.entries(SECTORS).map(([k,v])=>`<option value="${k}" ${k===sector?'selected':''}>${v.name}</option>`).join('')}</select></label><p>선택한 업종은 이 기기에 기억됩니다.</p>`);if(a==='notifications')modal('알림',`<p>새로운 알림이 없습니다.</p>`);if(a==='bridge'){$('#dialog').close();location.hash='transfer'}if(a==='reverse'){$('#from').selectedIndex=1-$('#from').selectedIndex;$('#from').dispatchEvent(new Event('change',{bubbles:true}))}if(a==='copy'){try{await navigator.clipboard.writeText('FLOW26');toast('추천코드를 복사했습니다.')}catch{modal('추천코드 복사','<p>아래 코드를 선택해 복사해주세요.</p><input readonly value="FLOW26" aria-label="추천코드">')}}if(a==='share'){try{if(navigator.share)await navigator.share({title:'FLOW 초대',text:'FLOW 추천코드: FLOW26'});else{await navigator.clipboard.writeText('FLOW 추천코드: FLOW26');toast('초대 문구를 복사했습니다.')}}catch(err){if(err.name!=='AbortError')toast('추천코드 FLOW26을 직접 공유해주세요.')}}});
document.addEventListener('submit',e=>{if(e.target.id==='transfer-form'){e.preventDefault();const amount=Number($('#amount').value);if(!Number.isFinite(amount)||amount<=0||amount>6000)return;modal('전환 미리보기',`<p>${esc($('#from').value)} → ${esc($('#to').textContent)}</p><h2>${amount.toLocaleString()} FLOW</h2><p class="notice">시뮬레이션이 완료되었습니다. 실제 전송은 발생하지 않았습니다.</p>`)}if(e.target.id==='request-form'){e.preventDefault();const d=new FormData(e.target);modal('신청 내용 확인',`<p>신청자: ${esc(d.get('name'))}</p><p>${esc(d.get('topic'))}</p><p>희망일: ${esc(d.get('date'))}</p><p class="notice">데모 확인 완료. 실제 신청은 전송되지 않았습니다.</p>`)}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});render();
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'configure_workspace_sector',description:'화면의 업종을 코인, 물류 또는 창업으로 전환합니다. 실제 업무 데이터는 변경하지 않습니다.',inputSchema:{type:'object',properties:{sector:{type:'string',enum:['coin','logistics','startup']}},required:['sector'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){switchSector(input.sector);return {sector,menus:c().menus}}})}catch{}}
